'use strict';

/**
* Create a "generic" matrix (i.e., a two-dimensional ndarray).
*
* @module @stdlib/ndarray-matrix-generic
*
* @example
* var getShape = require( '@stdlib/ndarray-shape' );
* var GenericMatrix = require( '@stdlib/ndarray-matrix-generic' );
*
* var v = new GenericMatrix();
* // returns <ndarray>
*
* var sh = getShape( v );
* // returns [ 0, 0 ]
*
* @example
* var getShape = require( '@stdlib/ndarray-shape' );
* var GenericMatrix = require( '@stdlib/ndarray-matrix-generic' );
*
* var v = new GenericMatrix( [ 2, 2 ] );
* // returns <ndarray>
*
* var sh = getShape( v );
* // returns [ 2, 2 ]
*
* @example
* var getShape = require( '@stdlib/ndarray-shape' );
* var GenericMatrix = require( '@stdlib/ndarray-matrix-generic' );
*
* var v = new GenericMatrix( 2, 2 );
* // returns <ndarray>
*
* var sh = getShape( v );
* // returns [ 2, 2 ]
*
* @example
* var getShape = require( '@stdlib/ndarray-shape' );
* var GenericMatrix = require( '@stdlib/ndarray-matrix-generic' );
*
* var v = new GenericMatrix( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] );
* // returns <ndarray>
*
* var sh = getShape( v );
* // returns [ 2, 2 ]
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
